#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    char instrucoes[30];
    if (scanf("%s", instrucoes) != 1) {
        return 0;
    }

    long long sala_atual = 1;

    for (int i = 0; i < n; i++) {
        if (instrucoes[i] == 'E') {
            sala_atual = 2 * sala_atual;
        } else if (instrucoes[i] == 'D') {
            sala_atual = 2 * sala_atual + 1;
        }
    }

    printf("%lld\n", sala_atual);

    return 0;
}
